import io
import json

import fastavro


def serialize_binary(*, payload, schema):
    """Serialize using avro binary format."""
    file_like_output = io.BytesIO()
    fastavro.schemaless_writer(file_like_output, schema, payload)
    value = file_like_output.getvalue()
    file_like_output.flush()
    return value


def serialize_json(*, payload, schema):
    """Serialize using avro-json format."""
    file_like_output = io.StringIO()
    fastavro.json_writer(file_like_output, schema, [payload])
    value = file_like_output.getvalue().strip()
    file_like_output.flush()
    return value


