        print(f"✓ Binary serialization: {binary_result}")

        # Test JSON serialization
        json_result = serialize_json(payload=data, schema=schema)
        print(f"✓ JSON serialization: {json_result}")

        # Try to parse the JSON result to make sure it's valid
        json_data = json.loads(json_result)
        print(f"✓ JSON is valid: {json_data}")

