"""

import io
import json

import fastavro
import pytest


def test_recursive_schema_json_serialization():
    """Test that recursive schemas can be serialized to JSON without RecursionError."""
    # Schema with recursive relationship (User with friend field pointing to User)
    schema = {
        'type': 'record', 
        'name': 'User', 
        'fields': [
            {'name': 'name', 'type': 'string'}, 
            {'name': 'age', 'type': 'long'}, 
            {'name': 'friend', 'type': ['null', 'User'], 'default': None}
        ]
    }

    # Test data with nested recursive structure
    data = {
        "name": "juan",
        "age": 20,
        "friend": {
            "name": "john",
            "age": 20,
        },
    }

    # This should not raise RecursionError
    file_like_output = io.StringIO()
    fastavro.json_writer(file_like_output, schema, [data])
    json_result = file_like_output.getvalue().strip()
    file_like_output.flush()

    # Validate that we got valid JSON
    parsed_json = json.loads(json_result)
    assert isinstance(parsed_json, list)
    assert len(parsed_json) == 1
    assert parsed_json[0]["name"] == "juan"
    assert parsed_json[0]["age"] == 20
    assert parsed_json[0]["friend"]["User"]["name"] == "john"


